cat > /tmp/repro.py <<'EOF'
import attr
import inspect

class MyClass:
    def __attrs_pre_init__(self, a, b):
        self.pre_a = a
        self.pre_b = b

@attr.s
class MyClassAttr(MyClass):
    a = attr.ib()
    b = attr.ib()

try:
    obj = MyClassAttr(a=1, b=2)
    assert obj.pre_a == 1
    assert obj.pre_b == 2
    print("REPRO PASS")
except TypeError as e:
    print(f"REPRO FAIL: {e}")
except AssertionError as e:
    print("REPRO FAIL: Assertion failed")
EOF
python3 /tmp/repro.py

cat <<'EOF' > /tmp/repro.py
import attr
import inspect

class MyClass:
    def __attrs_pre_init__(self, a):
        print(f"Pre-init called with a={a}")
        self.pre_init_called = True

    pre_init_called = False

@attr.s
class MyClassAttr(MyClass):
    a = attr.ib()

try:
    obj = MyClassAttr(a=1)
    print(f"pre_init_called: {obj.pre_init_called}")
    assert obj.pre_init_called is True
except TypeError as e:
    print(f"Caught expected TypeError: {e}")
    assert False, "Should not have raised TypeError"
except Exception as e:
    print(f"Caught unexpected exception: {type(e).__name__}: {e}")
    raise e

if __name__ == "__main__":
    print("Repro passed!")
EOF
